"""Assemble results/RESULTS.md from the JSON/CSV files written by the other scripts."""
import collections, csv, datetime, json
from _common import RESULTS, CONFIGS
import yaml

def J(name):
    p = RESULTS / name
    return json.loads(p.read_text()) if p.exists() else None

summ = J("summary_test.json"); by_kind = J("summary_by_kind_test.json"); abl = J("ablation_test.json")
tune = J("tuning.json"); prio = J("priority_model_report.json"); txt = J("text_classifier_report.json")
scene = J("scene_context_report.json"); lat = J("latency.json")
deep = J("deep_context_report.json"); export = J("export_report.json")
tuned = yaml.safe_load((CONFIGS / "cacs_tuned.yaml").read_text())["cacs"]

hedged = collections.defaultdict(lambda: [0, 0, 0])
for r in csv.DictReader(open(RESULTS / "per_scenario_test.csv")):
    a = hedged[r["policy"]]; a[0] += int(r["n_cues"]); a[1] += int(r["n_hedged"]); a[2] += int(r["n_false_positive_cues"])
n_runs = collections.Counter(r["policy"] for r in csv.DictReader(open(RESULTS / "per_scenario_test.csv")))

def f(x, d=3):
    return "n/a" if x is None or x != x else f"{x:.{d}f}"

L = []
L.append(f"# SeeForMe results ({datetime.date.today().isoformat()})\n")
L.append("Generated by `scripts/write_results_md.py` from the files in `results/`. Every number below is reproducible with `make all && make latency && make report`.\n")

L.append("## 1. Setup\n")
L.append("* **Benchmark.** Synthetic scenarios from `seeforme/sim/scenario.py`: six scene types (hallway, office, street, cluttered room, low light, text corridor), 30 s each at 10 detections/s, with a noisy detector model (missed detections that depend on object size, confidence noise, label confusions, OCR character corruptions, clutter false positives, low-light/blur degradation). Every object carries ground-truth *important windows*.")
L.append("* **Splits.** train = 36 scenarios (used to tune CACS weights and train the learned models), val = 18 (model selection and learned-model thresholds), test = 36 (all numbers below). Each test scenario is run with 3 detector-noise seeds, so each policy is scored on "
         f"{max(n_runs.values())} runs covering {36*3} × ~5 = ~550 important events.")
L.append("* **Audio channel.** All policies share the same channel model: one message at a time, occupying the channel for max(1.2 s, 0.35 s × words). Decisions every 0.5 s.")
L.append("* **Metrics** (section 5 of the proposal): important-cue recall, cue precision (a cue is useful if its object is inside an important window and was not announced in the previous 6 s), audio load (cues/min), duplicate rate, critical-event delay (s from window start to first announcement).\n")

L.append("## 2. Main result: baselines vs CACS (held-out test split)\n")
L.append("| policy | important-cue recall | cue precision | audio load (cues/min) | duplicate rate | mean critical delay (s) | hedged cues |")
L.append("|---|---|---|---|---|---|---|")
for p, a in summ.items():
    n, h, _ = hedged[p]
    L.append(f"| {p} | {f(a['important_cue_recall'])} ± {f(a['recall_sd'],2)} | {f(a['cue_precision'])} | {f(a['audio_load_per_min'],1)} ± {f(a['audio_load_sd'],1)} | {f(a['duplicate_rate'])} | {f(a['mean_critical_delay'],2)} | {h}/{n} |")
c, b1, b2 = summ["cacs"], summ["confidence_threshold"], summ["confidence_cooldown"]
L.append("")
L.append(f"**Answer to the research question.** CACS speaks {f(c['audio_load_per_min'],1)} cues/min instead of {f(b1['audio_load_per_min'],1)} (confidence threshold) or {f(b2['audio_load_per_min'],1)} (confidence + cooldown), a "
         f"{100*(1-c['audio_load_per_min']/b2['audio_load_per_min']):.0f}% reduction in audio load, while *raising* important-cue recall from {f(b1['important_cue_recall'],2)} / {f(b2['important_cue_recall'],2)} to {f(c['important_cue_recall'],2)} and cue precision from {f(b1['cue_precision'],2)} / {f(b2['cue_precision'],2)} to {f(c['cue_precision'],2)}. "
         f"Duplicate rate falls from {f(b1['duplicate_rate'],2)} to {f(c['duplicate_rate'],3)}. Critical-event delay is also lower ({f(c['mean_critical_delay'],2)} s vs {f(b1['mean_critical_delay'],2)} s) because the baselines waste the audio channel on background objects while an obstacle approaches.")
L.append("")
L.append("The baselines are not straw men: baseline 1 cycles through every confident detection (a queue, so nothing is skipped) and baseline 2 adds a 5 s per-label cooldown. Both keep the channel saturated with high-confidence background objects (clock, tv, cell phone, decorative signs) because model confidence is not user importance, exactly the failure mode described in section 3 of the proposal. No policy ever spoke a clutter false positive (all 0), because the tracker's two-hit confirmation filters transient detections before any policy sees them.")
L.append("")
L.append("`results/demo_hallway_*.mp4` show the same hallway scenario under each policy: the confidence baseline says \"clock / tv / cell phone / person\" 19 times in 30 s; CACS speaks 5 times, each about an obstacle entering the walking path or the STAIRS sign.\n")

L.append("### 2.1 Recall by scenario type\n")
pols = list(next(iter(by_kind.values())).keys())
L.append("| scenario | " + " | ".join(pols) + " |"); L.append("|---|" + "---|" * len(pols))
for k, v in by_kind.items():
    L.append(f"| {k} | " + " | ".join(f(v[p]['important_cue_recall'], 2) for p in pols) + " |")
L.append("")
L.append("**Failure case.** *street* is the one scene type where the cooldown baseline beats linear CACS on recall (cars passing laterally are important for only ~2 s, and the proximity feature, which rewards large, low, central boxes, undervalues a car crossing at mid-height). The gradient-boosted learned model recovers most of that recall, which suggests the fix is a motion-aware proximity term rather than a different weighting.\n")

L.append("## 3. Manual vs learned weighting\n")
w = tune["weights"]
L.append(f"**Tuned linear CACS** (random search on the train split, objective = F1 of recall and precision, {len(tune['history'])-1} trials): "
         f"α(confidence)={w['alpha']:.2f}, β(relevance)={w['beta']:.2f}, γ(novelty)={w['gamma']:.2f}, δ(proximity)={w['delta']:.2f}, η(text)={w['eta']:.2f}, λ(duplicate)={w['lam']:.2f}, threshold={tune['threshold']:.2f}, duplicate time constant={tuned['duplicate_tau']} s. "
         f"Train-split F1 rose from {tune['history'][0]['f1']:.3f} (hand-set defaults) to {tune['best_f1']:.3f}.")
L.append("")
lw = prio["models"]["logreg"]["learned_weights"]
L.append(f"**Learned models** are trained on {prio['n_train']:,} (observation, useful-now) pairs from the train split (positive rate {100*prio['pos_rate_train']:.1f}%) and validated on {prio['n_val']:,} from val:")
L.append("")
L.append("| model | val AUC | val average precision | val F1 at chosen threshold | threshold (chosen on val) |")
L.append("|---|---|---|---|---|")
for m, r in prio["models"].items():
    L.append(f"| {m} | {f(r['val_auc'])} | {f(r['val_ap'])} | {f(r.get('val_f1@best'))} | {f(r.get('val_threshold'),2)} |")
L.append("")
L.append("Logistic-regression coefficients (standardised inputs not used, so these are on the raw [0,1] features): " + ", ".join(f"{k}={v:+.1f}" for k, v in lw.items()) + ". "
         "The learned ordering, proximity > text importance > novelty > |duplicate| > relevance > confidence, matches the tuned manual weights: **confidence is the least useful signal for deciding what to say**, which is the proposal's central claim.")
L.append("")
L.append("These first learned variants (`cacs_learned:*`) were trained *off-policy*: their announcement history came from a noisy oracle, not from their own closed-loop behaviour, and their thresholds were chosen for single-decision F1 rather than for the closed-loop trade-off. Section 3.1 fixes both.\n")

# ---- on-policy + deep context -------------------------------------------------
if deep:
    L.append("### 3.1 On-policy training (DAgger) and the deep context model\n")
    L.append(f"All models in this section are trained on {deep['n_oracle_rows']:,} oracle-labelled candidate observations (positive rate {100*deep['pos_rate']:.1f}%) "
             f"and then improved with DAgger: the current model is run in closed loop on the train split, the states it actually visits are labelled by the oracle, aggregated, and the model is retrained. "
             "Thresholds are selected by *closed-loop* F1 on the validation split. The deep context model is a GRU over the last 8 decision steps of each track "
             "(13 signals per step: the six CACS features plus position, size, growth rate, age, time since announcement, announcement count), trained first by imitation and then fine-tuned with REINFORCE "
             "(reward +1 useful cue, −0.5 useless cue, −0.75 duplicate, −0.25 for staying silent while a useful candidate is visible; the audio channel is part of the environment).")
    L.append("")
    L.append("| model | inputs | DAgger iterations (val F1 per iteration) | chosen iteration | threshold | val F1 | test recall | test precision | test cues/min |")
    L.append("|---|---|---|---|---|---|---|---|---|")
    def testrow(pname):
        a = summ.get(pname)
        return (f(a['important_cue_recall']), f(a['cue_precision']), f(a['audio_load_per_min'], 1)) if a else ("n/a",)*3
    for name, r in deep["dagger"].items():
        iters = " → ".join(f"{h['f1']:.3f}" for h in r["history"])
        tr = testrow(f"cacs_dagger:{name}")
        L.append(f"| {name} (DAgger) | {r['n_features']} | {iters} | {r['best_iter']} | {r['threshold']} | {f(r['val_f1'])} | {tr[0]} | {tr[1]} | {tr[2]} |")
    r = deep["seq_il"]; iters = " → ".join(f"{h['f1']:.3f}" for h in r["history"]); tr = testrow("cacs_seq_il")
    L.append(f"| GRU sequence, imitation | 13 × 8 steps | {iters} | {r['best_iter']} | {r['threshold']} | {f(r['val_f1'])} | {tr[0]} | {tr[1]} | {tr[2]} |")
    r = deep["seq_rl"]; tr = testrow("cacs_seq_rl")
    curve = " → ".join(f"{h['f1']:.3f}" for h in r["history"][:: max(1, len(r['history']) // 5)])
    L.append(f"| GRU sequence, REINFORCE fine-tune | 13 × 8 steps | epochs: {curve} | best epoch | argmax vs silence | {f(r['val_f1'])} | {tr[0]} | {tr[1]} | {tr[2]} |")
    L.append("")
    lw = deep["dagger"]["logreg"].get("learned_weights", {})
    if lw:
        L.append("DAgger logistic-regression coefficients: " + ", ".join(f"{k}={v:+.1f}" for k, v in lw.items()) + ".")
    L.append("")
    def f1(a):
        r, pr = a["important_cue_recall"], a["cue_precision"]
        return 2 * r * pr / (r + pr) if r + pr > 0 else 0.0
    learned = [k for k in summ if k.startswith(("cacs_dagger", "cacs_seq", "cacs_learned"))]
    best_f1 = max(summ, key=lambda k: f1(summ[k]))
    best_rec = max(summ, key=lambda k: summ[k]["important_cue_recall"])
    best_learned = max(learned, key=lambda k: f1(summ[k]))
    c = summ["cacs"]; b = summ[best_learned]
    L.append("### 3.2 Interpretation\n")
    L.append("| policy | F1 (recall, precision) | recall | precision | cues/min | critical delay (s) |")
    L.append("|---|---|---|---|---|---|")
    for k in ["cacs"] + learned:
        a = summ[k]
        L.append(f"| {k} | {f1(a):.3f} | {f(a['important_cue_recall'])} | {f(a['cue_precision'])} | {f(a['audio_load_per_min'],1)} | {f(a['mean_critical_delay'],2)} |")
    L.append("")
    def d(k1, k2, m):
        return summ[k2][m] - summ[k1][m]
    L.append(f"* **DAgger works.** Training on the states a policy actually visits improves every feature model over its off-policy twin: "
             f"logreg recall {d('cacs_learned:logreg','cacs_dagger:logreg','important_cue_recall'):+.2f} / precision {d('cacs_learned:logreg','cacs_dagger:logreg','cue_precision'):+.2f}, "
             f"GBM {d('cacs_learned:gbm','cacs_dagger:gbm','important_cue_recall'):+.2f} / {d('cacs_learned:gbm','cacs_dagger:gbm','cue_precision'):+.2f}, "
             f"MLP {d('cacs_learned:mlp_torch','cacs_dagger:mlp13','important_cue_recall'):+.2f} / {d('cacs_learned:mlp_torch','cacs_dagger:mlp13','cue_precision'):+.2f} (the MLP also gains the seven extra inputs).")
    L.append(f"* **Reward fine-tuning is what makes the sequence model competitive.** Imitation alone leaves the GRU at recall {f(summ['cacs_seq_il']['important_cue_recall'],2)} / precision {f(summ['cacs_seq_il']['cue_precision'],2)}; "
             f"REINFORCE in closed loop lifts it to {f(summ['cacs_seq_rl']['important_cue_recall'],2)} / {f(summ['cacs_seq_rl']['cue_precision'],2)}, the highest recall of any policy, "
             f"with a critical-event delay of {f(summ['cacs_seq_rl']['mean_critical_delay'],2)} s against {f(c['mean_critical_delay'],2)} s for the linear rule: it learns to speak *while an object is still approaching* instead of waiting for the proximity term to grow.")
    L.append(f"* **The tuned linear rule is still the best single operating point** by F1 ({f1(c):.3f} vs {f1(summ[best_learned]):.3f} for `{best_learned}`), and it is the quietest and most precise policy. "
             f"The learned policies sit at a different point of the trade-off (about {f(b['audio_load_per_min'] - c['audio_load_per_min'],1)} more cues/min, {f(c['cue_precision'] - b['cue_precision'],2)} lower precision, faster reaction). "
             "Their validation F1 was higher than their test F1, so part of the gap is model/threshold selection on only 18 validation scenarios: the honest reading is that learned weighting matches manual weighting on this benchmark rather than beating it, and that the recall/latency gains are real while the precision cost is real too.")
    L.append("* **What this means for the thesis question.** Both the hand-tuned rule and the learned policies agree on *what matters*: proximity and text importance first, novelty and duplicate memory next, confidence last. Manual vs learned weighting is a secondary question; the primary result, a 75% cut in audio load with higher important-cue recall than either baseline, holds for every CACS variant.\n")

if export:
    L.append("### 6.1 Deployment export\n")
    for kind, r in export["exports"].items():
        if "error" in r:
            L.append(f"* **{kind}**: export failed ({r['error'].split(':')[0]}); with this PyTorch/coremltools pairing the Core ML converter rejects the attention block. Options: the Ultralytics cloud exporter, or a pinned older PyTorch in a separate environment.")
        else:
            extra = f", onnxruntime CPU {r['onnxruntime_cpu_ms_mean']} ms/frame (p95 {r['onnxruntime_cpu_ms_p95']} ms)" if "onnxruntime_cpu_ms_mean" in r else ""
            L.append(f"* **{kind}**: `{r['path']}`, {r['size_mb']} MB{extra}. This is the artefact a browser demo (onnxruntime-web) or an Android app consumes; the CACS layer ports as six numbers plus the tracker.")
    L.append("")

L.append("## 7. Limitations and next steps\n")
L.append("1. **Synthetic benchmark.** Object trajectories, detector noise and importance windows are simulated. The numbers show the *relative* behaviour of the policies under identical perception noise; absolute values will differ on real video. `scripts/run_video.py` + `scripts/score_video.py` and `docs/annotation_format.md` are ready for hand-annotated recordings (planned for the weeks of Nov 2–9 in the proposal schedule).")
L.append("2. **Ground truth is a proxy for user importance.** Important windows are defined geometrically (object enters the walking path, sign becomes legible). A study with blind and low-vision participants is out of scope for the semester, as stated in the proposal.")
L.append("3. **Learned models.** Section 3.1 trains on-policy (DAgger) and adds a sequence model with REINFORCE fine-tuning; a vision-language model fine-tuned on cue selection (LLaVA / InternVL, as in the expanded plan) remains future work because it needs GPU time and real annotated video.")
L.append("4. **Proximity is monocular.** A depth estimate (or bbox-height-to-distance using `TYPICAL_HEIGHT_M`) would fix the street failure case and make the proximity term physically meaningful.")
L.append("")
L.append("Figures: `results/figures/main_results.png`, `tradeoff.png`, `recall_by_kind.png`, `ablation.png`, `learned_weights.png`, `deep_context_training.png`, `poster_results.png` (compact, for the poster).")
(RESULTS / "RESULTS.md").write_text("\n".join(L) + "\n")
print("wrote", RESULTS / "RESULTS.md")
